#[component]
pub fn BrandLogo(
    icon: SimpleIcon,
    #[props(optional)] size: Option<u32>,
    #[props(optional)] class: Option<String>,
) -> Element {
    let size = size.unwrap_or(24);
    rsx! {
        svg {
            class: format!("text-seasalt-400 {}", class.unwrap_or_default()),
            view_box: {icon.view_box},
            "aria-hidden": "true",
            width: {size},
            height: {size},
            fill: "currentColor",
            path { d: {icon.path} }
        }
    }
}
